text:
.sync-type-container {
  inline-size: 100%;
  position: relative;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--color-surface-border);
  border-radius: 8px;
  block-size: 240px;
  font-size: 1.1rem;
  margin: 0;
  padding: 0;
  background-color: var(--color-surface-base);
  overflow: hidden;
  min-inline-size: 0;

  & .sync-title {
    display: flex;
    flex-direction: row;
    align-items: center;
    gap: var(--hub-sync-list-title-gap);
    padding: var(--hub-sync-list-title-padding);
    font-weight: bold;
    background-color: var(--color-surface-lower);
    border-block-end: 1px solid var(--color-surface-border);
    border-radius: 8px 8px 0 0;

    & .sync-details {
      display: flex;
      flex-direction: column;
      gap: var(--hub-sync-list-details-gap);
      flex-grow: 1;

      & .title {
        color: var(--color-text-base);
        text-transform: capitalize;
        margin-block: 0;
        font-size: 1rem;
      }

      & .subtitle {
        font-size: 0.9rem;
        color: var(--color-primary-default);
      }
    }

    & .sync-icon {
      inline-size: var(--hub-sync-list-icon-size);
      block-size: var(--hub-sync-list-icon-size);

      &.calendar {
        content: var(--hub-sync-list-calendar-icon);
      }

      &.address-book {
        content: var(--hub-sync-list-addressbook-icon);
      }
    }
  }

  & .sync-input-container {
    display: flex;
    flex-direction: column;
    position: relative;
    overflow-y: auto;
  }

  & .select-all {
    line-height: var(--hub-floating-button-line-height);
    align-self: end;
    margin-inline: 0;
    margin-block: 0 -20px;
    z-index: 1;
  }
